772: export function pickEvent(state, rng = Math.random) {
773:   let pool = EVENTS.filter(e => !state.seenEvents.includes(e.id));
774:   if (!pool.length) pool = FALLBACK_EVENTS.slice();
775:   const ev = pool[Math.floor(rng() * pool.length)];
776:   const rival = state.rivals[Math.floor(rng() * state.rivals.length)];
777:   const clone = JSON.parse(JSON.stringify(ev));
778:   const swap = str => (str || '').replace(/\{rival\}/g, rival ? rival.name : 'a rival god');
779:   clone.title = swap(clone.title);
780:   clone.text = swap(clone.text);
781:   clone.rivalName = rival ? rival.name : 'a rival god';
782:   clone.choices = clone.choices.map(c => ({ ...c, result: swap(c.result) }));
783:   if (!state.seenEvents.includes(ev.id)) state.seenEvents.push(ev.id);
784:   return clone;
785: }
