787: export function endAeon(state, rng = Math.random) {
788:   const before = rankMap(state);
789:   const currentAge = Number.isFinite(state.age) && state.age >= AGE_START
790:     ? state.age
791:     : AGE_START + Math.max(0, (state.aeon || 1) - 1) * AGE_PER_AEON;
792:   const { gains, surges } = passiveTick(state, rng);
793:   state.aeon += 1;
794:   state.age = currentAge + AGE_PER_AEON;
795:   state.ap = apMax(state);
796:   state.lastRanks = before;
797:   const text = `The world turns. ${fmt(gains.followers)} souls join your flock, and devotion gathers in the dark.`;
798:   const textEs = `El mundo gira. ${fmt(gains.followers)} almas se unen a tu rebaño, y la devoción se reúne en la oscuridad.`;
799:   addLog(state, 'sun', text, 'faith', textEs);
800:   for (const s of surges) addLog(state, 'crown', s.text, 'rival', s.textEs);
801:   const milestone = AGE_MILESTONES[state.age];
802:   if (milestone) addLog(state, 'hourglass', milestone.en, 'divine', milestone.es);
803:   return { gains, surges, event: rng() < 0.72 ? pickEvent(state, rng) : null };
804: }

